INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('000888e7-88de-5217-a3c2-78659d24b88c', 'Canh khoai mỡ nấu tôm thịt', 'canh', 4, '["Khoai mỡ gọt vỏ, dùng dao nạo hoặc muỗng cạo nhuyễn thành bột mịn màu tím đặc trưng.", "Tôm bóc vỏ băm nhuyễn, thịt nạc băm nhỏ ướp chút hành tím, nước mắm, tiêu.", "Phi thơm hành tím băm trên nồi dầu nóng, xào săn tôm thịt băm.", "Đổ 1 lít nước vào đun sôi, từ từ cho khoai mỡ nạo vào khuấy đều tay theo một chiều để khoai tan mịn không vón cục.", "Đun sôi nhỏ lửa khoảng 8-10 phút đến khi canh khoai mỡ sánh mịn dẻo quánh, nêm nước mắm vừa ăn.", "Tắt bếp rắc nhiều ngò gai và rau om thái nhỏ tạo mùi thơm nức mũi."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('0256e3d5-c953-5180-b47f-0c1a5c731dc0', 'Súp kem nấm gà kiểu Âu', 'canh', 4, '["Nấm rơm hoặc nấm mỡ rửa sạch thái lát mỏng, thịt ức gà thái hạt lựu nhỏ.", "Làm nóng chảo với bơ lạt, phi thơm hành tây băm nhỏ.", "Cho nấm và ức gà vào xào săn trên lửa vừa trong 4 phút.", "Đổ 600ml nước luộc gà vào đun sôi hầm 10 phút.", "Thêm sữa tươi và kem tươi khuấy đều, hòa tan chút bột bắp tạo độ sánh mịn như nhung, rắc tiêu đen thơm ngát."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('02dc86e4-714c-50b4-a2de-1632b3cbd75d', 'Thịt bò né hoa thiên lý', 'man', 4, '["Thịt bò thăn thái lát mỏng ngang thớ, ướp tỏi băm, dầu hào, tiêu và chút bơ thơm.", "Hoa thiên lý nhặt rửa sạch, ngâm nước muối loãng 5 phút rồi để ráo.", "Làm nóng chảo gang với lửa lớn, cho 1 muỗng bơ lạt phi thơm tỏi băm.", "Cho thịt bò vào đảo nhanh tay 1 phút trên lửa lớn vừa chín tái thì cho hoa thiên lý vào đảo chung.", "Đảo đều trong 1 phút đến khi hoa thiên lý vừa chín tới giữ độ giòn ngọt, rắc tiêu rồi dọn ăn ngay trên chảo gang."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('07cca4e4-99c1-5a49-9e16-80a7dc688256', 'Rau muống luộc chấm tương bần', 'rau', 4, '["Rau muống nhặt khúc non, rửa sạch ngâm nước muối loãng.", "Đun nồi nước thật sôi trên lửa lớn, thả rau muống vào dìm ngập nước.", "Luộc khoảng 3 phút cho cọng rau vừa chín tới nhưng vẫn giữ độ xanh giòn.", "Vớt rau ra đĩa, vắt chút chanh hoặc thả vài quả sấu vào nồi nước luộc làm canh.", "Chấm rau cùng chén tương bần pha chút đường, ớt và vài lát gừng cay nồng."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('0921f7a2-2c1b-5a67-9ae0-e7fb7ad68c0c', 'Cá lóc kho tộ', 'man', 4, '["Cá lóc làm sạch vảy, cắt khúc dày 2.5cm, rửa với muối và chanh cho hết nhớt.", "Ướp cá với hành tím, ớt đập dập, 3 muỗng nước mắm ngon, 1.5 muỗng đường, nước màu dừa, tiêu 30 phút.", "Xếp thịt ba chỉ lát mỏng hoặc mỡ dưới đáy tộ đất, đặt các khúc cá lên trên.", "Bắc tộ lên bếp đun sôi trên lửa lớn cho cá săn chắc thịt.", "Đổ thêm 50ml nước nóng hoặc nước dừa, hạ lửa thật nhỏ kho liu riu 35 phút đến khi nước cạn sánh kẹo.", "Rắc hành lá, tiêu xay và vài lát ớt hiểm lên mặt trước khi bưng ra bàn ăn."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('0959dae9-e69b-536e-b230-3ba73911a8c6', 'Tôm rang thịt ba chỉ', 'man', 4, '["Thịt ba chỉ thái miếng mỏng vừa ăn, tôm cắt râu rửa sạch để ráo.", "Cho thịt ba chỉ vào chảo đảo trên lửa vừa cho tiết bớt mỡ và xém cạnh vàng giòn.", "Gạt thịt sang một bên, trút hành tỏi băm vào phi thơm trên phần mỡ heo.", "Cho tôm vào đảo đều trên lửa lớn đến khi tôm cong lại đỏ au.", "Nêm nước mắm, đường, chút nước màu đảo đều tay đến khi nước cạn keo bám bóng tôm thịt, rắc hành lá tiêu xay."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('0968834f-615f-58b5-bb27-e11121e4685e', 'Cà tím nướng mỡ hành', 'rau', 4, '["Cà tím dài để nguyên cuống, rửa sạch, dùng tăm xiên nhẹ vài lỗ quanh thân cà.", "Nướng cà tím trên than hoa hoặc nồi chiên không dầu 200°C trong 15 phút cho da cháy xém mềm nhũn.", "Lột bỏ lớp vỏ cháy bên ngoài, tách thịt cà tím xếp ra đĩa phẳng.", "Hành lá thái nhỏ cho vào chén cùng chút muối đường, đun sôi 3 muỗng dầu ăn rồi đổ vào chén hành làm mỡ hành thơm.", "Rưới mỡ hành, nước mắm tỏi ớt chua ngọt và rắc đậu phộng rang giã dập lên đĩa cà tím."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('0b1613ac-95e6-5086-bf15-533ab4640b82', 'Canh bầu nấu tôm tươi', 'canh', 4, '["Quả bầu non gọt vỏ, băm hoặc thái sợi mỏng dài.", "Tôm đồng hoặc tôm sú bóc vỏ băm nhỏ, ướp chút hành tím nước mắm tiêu.", "Phi thơm hành tím trên nồi dầu nóng, xào săn tôm thơm lừng.", "Đổ 1 lít nước vào đun sôi, thả bầu băm vào đun lửa lớn khoảng 2 phút đến khi miếng bầu trong suốt.", "Nêm nước mắm vừa miệng, rắc nhiều hành hoa và mùi ngò thơm nức mũi."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('0dd28595-b297-5548-b67d-2a545ea1bafb', 'Gỏi ngó sen tôm thịt', 'rau', 4, '["Ngó sen chẻ đôi cắt khúc, ngâm nước đá có pha giấm đường để ngó sen trắng giòn.", "Thịt ba chỉ luộc chín thái mỏng, tôm luộc chín bóc vỏ chẻ đôi sống lưng.", "Cà rốt bào sợi, dưa leo bỏ ruột thái lát, rau răm thái nhỏ, đậu phộng rang giã dập.", "Pha nước mắm gỏi: 3 muỗng nước mắm, 3 muỗng đường, 2.5 muỗng nước cốt chanh, tỏi ớt băm nhuyễn.", "Vắt ráo ngó sen cà rốt, trộn đều cùng tôm thịt, rau răm và nước mắm chua ngọt, rắc đậu phộng lên trên."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('0f89a406-db57-5a2a-a3c5-7c347e8d25e9', 'Bắp cải luộc dầm trứng nước mắm', 'rau', 4, '["Bắp cải rửa sạch, cắt miếng tam giác to bản vừa ăn.", "Đun sôi nồi nước với vài hạt muối và một nhánh gừng đập dập.", "Thả bắp cải vào luộc trên lửa lớn khoảng 4-5 phút đến khi bắp cải chín trong mềm ngọt.", "Vớt bắp cải ra đĩa sâu lòng, giữ lại nước luộc làm canh thanh mát.", "Luộc chín lòng đào 2 quả trứng vịt (hoặc trứng gà), dầm nát vào chén nước mắm nhĩ ngon nhiều ớt để chấm rau."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('0f8d3ac7-ec70-5bae-9c65-bc68be367e3b', 'Súp bí đỏ kem sữa tươi kiểu Pháp', 'canh', 4, '["Bí đỏ gọt vỏ bỏ hạt cắt miếng nhỏ, hành tây thái hạt lựu.", "Làm nóng nồi với 20g bơ lạt, phi thơm hành tây cho mềm thơm.", "Cho bí đỏ vào xào cùng hành tây 3 phút, đổ 600ml nước hầm xương vào đun sôi hầm 15 phút cho bí chín mềm nhừ.", "Dùng máy xay cầm tay xay nhuyễn mịn trực tiếp trong nồi.", "Đổ sữa tươi không đường và kem sữa (whipping cream) vào khuấy đều trên lửa nhỏ, nêm chút muối tiêu vừa vị béo ngậy mịn màng."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('10ac6e85-a5ad-565b-9ccd-d14811b6f4c4', 'Cánh gà nướng sốt BBQ mật ong', 'man', 4, '["Cánh gà rửa sạch khía vài đường trên mình thịt cho ngấm gia vị.", "Pha sốt ướp: sốt BBQ, mật ong, nước tương, dầu hào, tỏi băm, tiêu xay.", "Ướp cánh gà với sốt BBQ trong ít nhất 30 phút (hoặc để ngăn mát qua đêm).", "Xếp gà vào khay nướng ở 190°C trong 20 phút, lật mặt quét thêm lớp sốt mật ong.", "Nướng tiếp 10 phút đến khi da gà cánh gián nâu bóng vàng giòn thơm nức mũi."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('13c2b68a-d12d-5925-8be6-e85067f293fa', 'Salad cá ngừ trứng luộc sốt Mayonnaise', 'rau', 4, '["Xà lách rửa sạch ngâm nước đá cho giòn ráo, xé miếng vừa ăn.", "Cà chua bi bổ đôi, dưa chuột thái lát tròn, hành tây thái mỏng ngâm giấm đường khử hăng.", "Trứng gà luộc chín tới, bóc vỏ bổ múi cau.", "Cá ngừ ngâm dầu đóng hộp chắt bớt dầu, dằm nhẹ thành miếng nhỏ.", "Xếp xà lách, cà chua, dưa chuột ra đĩa lớn, cho cá ngừ và trứng luộc lên trên, rưới sốt Mayonnaise pha chút cốt chanh và tiêu xay."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('13f374af-f020-5577-9943-063d22aa96e3', 'Cơm chiên Dương Châu lạp xưởng tôm', 'man', 4, '["Lạp xưởng luộc sơ thái hạt lựu, tôm sú bóc vỏ thái hạt lựu.", "Cà rốt, đậu cô ve chần sơ nước sôi thái hạt lựu, trứng gà đánh tan chiên mỏng thái sợi.", "Trộn cơm nguội với 1 lòng đỏ trứng gà và chút dầu ăn để hạt cơm áo màu vàng óng.", "Phi thơm hành tỏi trên chảo lớn lửa to, xào tôm lạp xưởng cho săn thơm rồi trút rau củ vào đảo đều.", "Cho cơm vào đảo nhanh tay trên lửa lớn đến khi hạt cơm săn giòn tách rời, nêm nước tương tiêu rắc hành hoa."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('1868755f-b247-5c4e-8186-68da190b5117', 'Canh bí đỏ thịt băm', 'canh', 4, '["Bí đỏ gọt vỏ, nạo bỏ ruột hạt, rửa sạch, cắt miếng vuông quân cờ vừa ăn.", "Thịt nạc băm ướp chút hạt nêm, tiêu và hành tím băm nhỏ 10 phút.", "Phi thơm hành tím trong nồi với chút dầu ăn, trút thịt băm vào xào săn chín tới.", "Đổ 1 lít nước vào đun sôi, thả bí đỏ vào nấu trên lửa vừa khoảng 12 phút cho bí chín mềm bùi.", "Nêm nước mắm hạt nêm vừa vị ngọt dịu, rắc rau ngò ôm (rau ngổ) và mùi tàu thái nhỏ rồi tắt bếp."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('19f6c287-3cf7-5f9c-a568-485a8ac42fa7', 'Cánh gà sốt me chua ngọt', 'man', 4, '["Cánh gà rửa sạch, chặt 3 khúc, ướp chút hạt nêm, tiêu và hành tỏi băm 15 phút.", "Chiên cánh gà ngập dầu đến khi vàng giòn hai mặt.", "Me chín ngâm nước ấm dầm nát, lọc lấy nước cốt me.", "Pha nước sốt me: nước cốt me, đường, nước mắm, tương ớt khuấy tan.", "Phi thơm tỏi ớt băm, đổ sốt me vào đun sôi lăn tăn, cho cánh gà chiên vào đảo đều đến khi sốt keo bóng."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('1bd57492-4cd5-5648-8ee5-e20df510a9ad', 'Chả cá thát lát chiên cốm', 'man', 4, '["Cá thát lát nạo sẵn quết thật kỹ cùng hành tím băm, thì là băm nhuyễn, nước mắm, tiêu hạt cho dai dẻo.", "Thoa dầu ăn vào tay, nặn chả cá thành các viên tròn dẹt vừa ăn.", "Lăn từng miếng chả cá qua một lớp cốm dẹp xanh cho cốm bám đều quanh bề mặt.", "Đun nóng chảo dầu trên lửa vừa, thả chả cá vào chiên đến khi hạt cốm phồng giòn rụm và chả chín thơm.", "Vớt ra giấy thấm dầu, ăn nóng chấm tương ớt hoặc sốt mayonnaise."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('1dddd2b5-1694-588d-bc82-78435fd85af4', 'Canh cải bẹ xanh nấu gừng cá rô', 'canh', 4, '["Cá rô đồng làm sạch luộc chín với gừng, gỡ lấy thịt ướp nước mắm tiêu, phần xương giã lọc lấy nước ngọt.", "Cải bẹ xanh rửa sạch cắt khúc 3cm, gừng cạo vỏ thái sợi mỏng.", "Phi thơm hành tím xào sơ thịt cá rô cho săn thơm.", "Đổ nước hầm xương cá vào đun sôi cùng gừng thái sợi ấm bụng.", "Thả cải bẹ xanh vào nấu sôi 2 phút cho cải chín mềm vị cay nồng thanh mát, nêm nước mắm vừa ăn."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('22222222-0001-0000-0000-000000000001', 'Thịt kho tàu', 'man', 4, '["Ướp thịt ba chỉ với hành tím băm, nước mắm, tiêu trong 20 phút.", "Luộc trứng vịt chín rồi bóc vỏ.", "Thắng nước màu caramen, trút thịt vào đảo săn đều.", "Thêm nước vào nồi ngập thịt, kho riu riu.", "Cho trứng vịt vào kho cùng đến khi thịt mềm rục."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('22222222-0001-0000-0000-000000000002', 'Sườn xào chua ngọt', 'man', 4, '["Sườn non chặt miếng vừa ăn, chần qua nước sôi rồi để ráo.", "Chiên sườn vàng đều 2 mặt trên chảo dầu nóng.", "Pha sốt chua ngọt từ nước mắm, giấm gạo, đường và tương cà chua.", "Phi thơm tỏi, cho sườn và sốt đảo đều đến khi ngấm vị."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('22222222-0002-0000-0000-000000000001', 'Rau muống xào tỏi', 'rau', 4, '["Rau muống nhặt sạch, chần nhanh qua nước sôi.", "Phi thơm tỏi đập dập với dầu ăn trên chảo lửa lớn.", "Cho rau muống vào đảo nhanh tay, nêm gia vị vừa ăn rồi tắt bếp."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('22222222-0003-0000-0000-000000000001', 'Canh chua cá lóc', 'canh', 4, '["Cá lóc cắt khúc, cà chua bổ múi cau, thơm thái lát, đậu bắp cắt xéo.", "Phi thơm tỏi, cho cà chua và thơm vào xào lấy màu.", "Thêm nước sôi, thả cá lóc vào đun chín ngọt nước.", "Cho đậu bắp, giá đỗ vào nấu sôi lại, nêm nếm gia vị và rau ngò."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('267e2c7a-7b74-54f5-9cf9-8d44c586307f', 'Thịt băm viên sốt cà chua', 'man', 4, '["Thịt nạc vai xay nhuyễn trộn cùng hành tím băm, mộc nhĩ nấm mèo ngâm nở thái nhỏ, hạt nêm, tiêu.", "Vo thịt thành các viên tròn đường kính 3cm.", "Chiên sơ các viên thịt trong chảo dầu nóng cho săn mặt ngoài.", "Cà chua băm nhuyễn xào nhừ với hành phi thành sốt sệt, nêm nước mắm và chút đường.", "Thả các viên thịt vào sốt cà chua, đậy nắp om nhỏ lửa 15 phút cho ngấm đều, rắc hành lá."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('26d5e016-13cf-59fd-95d7-223de11cc717', 'Su su xào trứng', 'rau', 4, '["Su su gọt vỏ dưới vòi nước chảy để không dính mủ, bổ đôi bỏ hạt rồi thái sợi mỏng.", "Phi thơm hành tím băm với dầu ăn trên chảo nóng.", "Trút su su vào xào trên lửa lớn, nêm chút hạt nêm cho vừa miệng.", "Khi su su vừa chín tới, đập 2 quả trứng gà vào chảo, đảo nhanh tay cho trứng bám đều quanh sợi su su.", "Rắc hành lá cắt nhỏ và tiêu xay thơm nồng rồi tắt bếp."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('271f010b-ae8f-5259-ae70-c38cc4c4dd3f', 'Gà kho gừng', 'man', 4, '["Thịt gà ta chặt miếng vừa ăn, bóp muối và rượu trắng rửa sạch, để ráo.", "Gừng cạo vỏ, 1 nửa băm nhỏ ướp gà, 1 nửa thái sợi dài.", "Ướp gà với gừng băm, hành tím băm, 2 muỗng nước mắm, 1 muỗng hạt nêm, tiêu trong 20 phút.", "Thắng nước màu đường trong chảo, phi thơm gừng thái sợi rồi trút gà vào xào săn trên lửa lớn.", "Hạ nhỏ lửa, đậy vung kho khoảng 15 phút đến khi gà chín mềm, nước kho sánh thơm nức mùi gừng."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('2a627a10-ca8f-5aa5-8ffc-ea8314b63c89', 'Cà ri gà kiểu Nhật Bản', 'man', 4, '["Thịt đùi gà rút xương cắt miếng vuông 3cm, khoai tây và cà rốt gọt vỏ cắt khối vừa ăn, hành tây thái múi cau.", "Xào thịt gà trên nồi lớn với chút dầu ăn cho săn vàng mặt ngoài.", "Cho hành tây, khoai tây và cà rốt vào xào chung trong 3 phút.", "Đổ 800ml nước vào đun sôi vớt bọt, hạ nhỏ lửa hầm 15 phút cho củ quả chín mềm.", "Thả viên sốt cà ri Nhật (hoặc bột cà ri) vào khuấy tan hoàn toàn, đun liu riu thêm 5 phút đến khi sốt cà ri sánh mịn thơm nức."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('2dd67426-2b93-51c7-b9de-be3188a3c5de', 'Canh chua cá lóc miền Tây', 'canh', 4, '["Cá lóc cắt khúc rửa sạch với chanh khử nhớt, để ráo.", "Cà chua bổ múi cau, thơm (dứa) thái lát, đậu bắp cắt xéo, dọc mùng tước vỏ bóp muối rửa sạch, giá đỗ rửa sạch.", "Me chín dầm với nước ấm lọc lấy nước cốt me chua thanh.", "Phi thơm tỏi băm trên nồi, cho cà chua và dứa vào xào thơm lấy màu đỏ cam đẹp.", "Đổ 1.2 lít nước vào đun sôi, thả cá lóc vào nấu chín trong 10 phút rồi nêm nước mắm, đường, cốt me.", "Thả đậu bắp, dọc mùng, giá đỗ vào đun sôi bùng lại rồi tắt bếp, rắc ngò gai rau om và tỏi phi thơm nức."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('2e2fcc9b-2425-5e3f-9645-7171139e696d', 'Dưa leo dầm tỏi ớt chua ngọt', 'rau', 4, '["Dưa leo rửa sạch ngâm muối loãng, bỏ bớt ruột, đập dập rồi cắt khúc 3cm.", "Tỏi bóc vỏ đập dập băm nhỏ, ớt hiểm thái lát mỏng.", "Pha nước trộn: 2 muỗng nước mắm, 2 muỗng đường, 2 muỗng giấm táo (hoặc chanh).", "Cho dưa leo vào âu lớn, đổ hỗn hợp nước mắm tỏi ớt vào xóc đều tay.", "Để trong ngăn mát tủ lạnh 15-20 phút cho dưa ngấm giòn lạnh chua ngọt khai vị rất ngon."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('2f8a2e0c-2c72-5403-a945-88ca41a4fd54', 'Canh chua tôm đậu bắp', 'canh', 4, '["Tôm sú lột vỏ chừa đuôi, rút chỉ đen trên lưng, rửa sạch để ráo.", "Đậu bắp cắt xéo, cà chua bổ múi cau, giá đỗ rửa sạch, me ngâm nước nóng lọc nước cốt.", "Phi thơm hành tỏi băm trong nồi, xào cà chua cho mềm đỏ.", "Đổ 1 lít nước lọc và nước cốt me vào đun sôi, thả tôm vào nấu khoảng 3 phút cho tôm chuyển màu đỏ au.", "Cho đậu bắp và giá đỗ vào đun sôi thêm 2 phút, nêm nước mắm đường vừa vị chua ngọt đậm đà, rắc rau ngò."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('2fb55f3c-2f1e-581e-afd4-71c486986382', 'Vịt kho gừng', 'man', 4, '["Thịt vịt rửa sạch với rượu trắng và gừng đập dập để khử sạch mùi hôi đặc trưng, chặt miếng vừa ăn.", "Gừng cạo vỏ, thái sợi hoặc thái lát dày đập dập.", "Ướp vịt với gừng, hành tím băm, nước mắm, đường, tiêu và nước màu dừa trong 25 phút.", "Bắc nồi lên bếp, phi thơm chút hành tím rồi cho thịt vịt vào xào săn trên lửa lớn.", "Hạ nhỏ lửa đun liu riu khoảng 20 phút đến khi thịt vịt mềm rục, nước kho sánh thơm nức mũi."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('2ff964e2-1d05-5668-9a1f-021b029d9396', 'Đậu cô ve xào thịt băm', 'rau', 4, '["Đậu cô ve tước xơ hai bên mép, rửa sạch, cắt khúc xéo vừa ăn.", "Thịt nạc băm ướp chút hạt nêm và tiêu.", "Phi thơm tỏi trên chảo, cho thịt băm vào xào săn chín tới rồi múc riêng ra đĩa.", "Tiếp tục cho đậu cô ve vào chảo xào với lửa lớn, thêm chút nước lọc để đậu nhanh chín mềm ngọt.", "Trút thịt băm trở lại chảo đảo đều cùng đậu cô ve trong 1 phút, rắc tiêu thơm."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('3155f8ce-2418-5ad5-832a-5fc7f9d38ed7', 'Chả giò nem rán truyền thống', 'man', 4, '["Thịt nạc vai băm nhỏ trộn tôm băm, mộc nhĩ, nấm hương ngâm nở thái chỉ, miến ngâm mềm cắt khúc.", "Cà rốt, củ đậu (hoặc su hào) bào sợi vắt bớt nước, hành lá thái nhỏ, đập 1 quả trứng vào trộn đều nhân.", "Trải bánh tráng ra mặt phẳng, múc lượng nhân vừa đủ cuộn tròn chặt tay vừa phải.", "Đun nóng dầu ăn ngập chảo, cho nem vào chiên lửa vừa đến khi chín đều rồi tăng lửa chiên vàng giòn rụm.", "Vớt nem ra đĩa có lót giấy thấm dầu, ăn kèm bún, rau sống và nước mắm chua ngọt tỏi ớt."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('31dbc3dc-072b-5c63-bc44-11314a03d367', 'Canh sườn nấu chua dứa cà chua', 'canh', 4, '["Sườn non chặt miếng vừa ăn, chần nước sôi rửa sạch.", "Dứa (thơm) gọt vỏ bỏ mắt, thái lát mỏng hình tam giác, cà chua bổ múi cau.", "Hầm sườn với 1 lít nước trên lửa vừa trong 25 phút cho thịt mềm ngọt nước.", "Phi thơm hành tím trên chảo xào cà chua và dứa lấy màu đẹp rồi trút vào nồi sườn.", "Nêm nước mắm hạt nêm đường vừa vị chua ngọt thanh mát, đun sôi 3 phút rắc hành lá thì là."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('3415f525-b225-5f6e-93de-5db3825f2085', 'Bò xào cần tỏi', 'man', 4, '["Thịt bò thăn thái lát mỏng ngang thớ, ướp tỏi băm, gừng, dầu hào, tiêu và chút dầu ăn.", "Cần tây nhặt sạch cắt khúc 4cm, hành tây bổ múi cau, tỏi tây cắt xéo, cà chua bổ múi cau.", "Làm nóng chảo với lửa lớn, phi thơm tỏi, cho thịt bò vào xào nhanh 1-2 phút vừa chín tới rồi trút ra đĩa.", "Tiếp tục cho cần tây, tỏi tây, hành tây, cà chua vào xào trên lửa lớn, nêm chút hạt nêm.", "Trút thịt bò trở lại đảo đều 30 giây, rắc tiêu thơm rồi tắt bếp."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('356894d4-0e3a-53ad-b935-d84a76ea69a7', 'Gà kho sả ớt cay nồng', 'man', 4, '["Thịt gà chặt miếng vừa ăn, rửa sạch để ráo.", "Sả băm nhỏ, ớt hiểm băm nhuyễn, tỏi băm thơm.", "Ướp thịt gà với 1/2 lượng sả ớt, nước mắm, hạt nêm, bột nghệ tạo màu trong 20 phút.", "Phi thơm lượng sả ớt còn lại trong chảo dầu nóng, trút gà vào xào săn vàng các mặt.", "Thêm 50ml nước lọc, đậy nắp kho lửa nhỏ 15 phút đến khi cạn nước, miếng gà thấm đẫm vị sả ớt cay thơm."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('365b86e1-7894-5f00-b7bf-806e7ae6726f', 'Bò xào bông cải xanh', 'man', 4, '["Thịt bò thái lát mỏng, ướp tỏi băm, dầu hào, nước tương và tiêu.", "Bông cải xanh (súp lơ) cắt miếng vừa ăn, ngâm nước muối loãng rồi chần sơ nước sôi.", "Cà rốt tỉa hoa thái lát mỏng.", "Xào thịt bò trên lửa lớn vừa chín tới thì trút riêng ra đĩa.", "Xào bông cải và cà rốt với chút dầu ăn và hạt nêm cho chín giòn, trút thịt bò vào đảo đều 1 phút."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('37eabc3e-5630-53fc-b9e7-4ebd80c70f5b', 'Sườn cừu áp chảo hương sả', 'man', 4, '["Sườn chặt từng giẻ rửa sạch thấm khô nước.", "Ướp sườn với sả băm nhuyễn, tỏi, nước mắm, mật ong, tiêu xay trong 30 phút.", "Làm nóng chảo với chút dầu ăn, cho sườn vào áp chảo lửa vừa mỗi mặt 4-5 phút cho vàng xém đẹp.", "Đậy nắp vung hạ nhỏ lửa thêm 3 phút để thịt bên trong chín mềm mọng nước.", "Gắp ra đĩa dùng cùng cơm hoặc khoai tây chiên."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('38bb0558-d493-5fcb-94b7-0c51dfd054f9', 'Gà sốt cay ngọt Hàn Quốc (Dakgangjeong)', 'man', 4, '["Thịt đùi hoặc cánh gà chặt miếng vừa ăn, ướp muối tiêu gừng băm trong 15 phút.", "Lăn thịt gà qua lớp bột bắp rồi chiên ngập dầu lần 1 trên lửa vừa đến khi chín vàng nhạt.", "Vớt gà ra để nghỉ 5 phút rồi chiên lại lần 2 trên lửa lớn trong 2 phút để lớp vỏ giòn tan không ngấy mỡ.", "Pha sốt: tương ớt Gochujang, tương cà, mật ong, nước tương, tỏi băm đun sôi sủi bọt trong chảo lớn.", "Trút gà chiên giòn vào chảo sốt đảo thật nhanh tay cho sốt bám đều óng ánh, rắc mè rang thơm."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('38c1cfbc-39ae-55a7-b8ab-ddcc67d1f587', 'Bò lúc lắc khoai tây', 'man', 4, '["Thịt bò thăn cắt khối vuông quân cờ 2x2cm, ướp tỏi băm, dầu hào, nước tương, đường, tiêu và bơ.", "Khoai tây gọt vỏ, cắt thanh dài, chiên vàng giòn trong dầu nóng rồi vớt ra để ráo.", "Ớt chuông và hành tây cắt miếng vuông vừa ăn.", "Bắc chảo gang lên bếp lửa lớn thật nóng, cho chút dầu và bơ phi thơm tỏi.", "Cho thịt bò vào lắc đều tay trên lửa cực lớn khoảng 2 phút cho xém cạnh ngoài nhưng mềm ngọt bên trong.", "Cho ớt chuông, hành tây vào đảo nhanh 1 phút, trút ra đĩa ăn kèm khoai tây chiên."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('38fc0dcd-6952-5a4f-894f-71d3e750ba75', 'Cá rô phi nướng sả ớt', 'man', 4, '["Cá rô phi đánh vảy làm sạch, khía xéo caro trên thân cá để ngấm gia vị.", "Giã nhuyễn hỗn hợp: sả băm, ớt hiểm, tỏi, gừng, nước mắm, dầu hào, đường.", "Xát đều hỗn hợp sả ớt vào bụng cá và các đường khía ngoài thân cá, ướp 30 phút.", "Nướng cá trên than hoa hoặc nồi chiên không dầu ở 180°C trong 20 phút, lật mặt nướng thêm 10 phút.", "Da cá vàng giòn thơm nức mùi sả ớt nướng, thịt bên trong trắng ngọt tự nhiên."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('4509521e-2cda-5972-b593-6f37d244ef00', 'Gà hấp lá chanh', 'man', 4, '["Gà ta làm sạch, xát muối và gừng khử mùi hôi, để ráo nước.", "Lá chanh rửa sạch, một nửa lót đáy xửng hấp, một nửa thái chỉ thật mỏng.", "Xát nhẹ chút muối và tiêu lên mình gà, đặt gà lên xửng hấp.", "Hấp gà trên lửa vừa trong 25-30 phút đến khi thịt gà chín tới, da căng bóng vàng óng.", "Chặt gà thành miếng vừa ăn, rải lá chanh thái chỉ lên trên, chấm muối tiêu chanh ớt."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('456c72c5-a6b5-5b42-ae3e-ecdf23b2207e', 'Đậu bắp luộc chấm chao', 'rau', 4, '["Đậu bắp rửa sạch, cắt bỏ phần cuống trên đầu nhưng không cắt sát vào trong ruột.", "Đun sôi nồi nước với chút muối hạt.", "Thả đậu bắp vào luộc khoảng 3-4 phút đến khi đậu chuyển màu xanh thẫm chín mềm.", "Vớt đậu bắp ra ngâm nhanh nước đá 1 phút cho giòn rồi xếp ra đĩa.", "Dầm 2 viên chao béo ngậy với chút đường, sa tế ớt để làm nước chấm thơm ngon độc đáo."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('457cc0da-5ada-530c-9a69-ccd12f0eae9c', 'Cá thu sốt cà chua', 'man', 4, '["Cá thu cắt khúc rửa sạch, thấm khô nước, ướp chút muối và tiêu 10 phút.", "Chiên cá thu trên chảo dầu nóng đến khi hai mặt vàng nhẹ thì gắp ra đĩa.", "Cà chua băm nhuyễn, phi thơm hành tím rồi trút cà chua vào xào nhuyễn thành sốt đỏ sệt.", "Nêm nước mắm, đường, chút hạt nêm vừa vị mặn ngọt hài hòa.", "Thả cá thu vào chảo sốt cà, rưới sốt lên mặt cá, đun nhỏ lửa 10 phút cho cá ngấm đều, rắc hành ngò."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('45981d45-9c09-5354-b8b4-0eef8632852b', 'Canh xà lách xoong nấu thịt bò', 'canh', 4, '["Rau xà lách xoong nhặt ngọn non rửa sạch nhiều lần để ráo.", "Thịt bò thăn thái lát mỏng ướp tỏi băm, tiêu, hạt nêm và chút dầu ăn.", "Phi thơm tỏi xào nhanh thịt bò vừa chín tái rồi múc riêng ra đĩa.", "Đổ 1 lít nước vào nồi đun sôi bùng nêm nước mắm hạt nêm vừa ăn.", "Thả xà lách xoong vào nấu sôi trong 1 phút, trút thịt bò vào đảo đều rồi tắt bếp ngay tránh rau nát."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('478eeb65-a3f5-5cf9-b807-f0b49a6e9ff0', 'Nộm su hào cà rốt chua ngọt', 'rau', 4, '["Su hào và cà rốt gọt vỏ, bào sợi mỏng dài.", "Trộn sợi su hào cà rốt với 1 muỗng muối hạt trong 10 phút, sau đó vắt nhẹ bỏ bớt nước để giữ độ giòn.", "Rau mùi, kinh giới rửa sạch thái nhỏ.", "Pha nước trộn: 2 muỗng giấm, 2 muỗng đường, 1.5 muỗng nước mắm ngon, tỏi ớt băm nhuyễn.", "Trộn đều su hào cà rốt với nước sốt chua ngọt và rau thơm, rắc đậu phộng rang giã dập lên trên."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('48e7b90b-9ea9-59f7-8e42-2c92d813518d', 'Canh đu đủ hầm sườn non', 'canh', 4, '["Đu đủ mỏ vịt (vừa hườm hoặc xanh) gọt vỏ rửa sạch mủ, cắt miếng vuông dày 3cm.", "Sườn non chặt khúc chần nước sôi rửa sạch bọt bẩn.", "Cho sườn vào nồi cùng 1.2 lít nước đun sôi vớt sạch bọt, hầm nhỏ lửa 20 phút cho ra nước ngọt.", "Thả đu đủ vào hầm chung thêm 15 phút đến khi đu đủ chín mềm bùi ngọt lịm.", "Nêm nước mắm hạt nêm vừa ăn, rắc hành ngò thái nhỏ và chút tiêu xay."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('4fb5a240-4b40-52f5-a2fb-d2100f7ce03c', 'Tép đồng rang khế chua', 'man', 4, '["Tép đồng hoặc tôm nhỏ nhặt sạch rác, rửa nước muối để ráo.", "Khế chua gọt rìa múi, thái lát mỏng hình ngôi sao.", "Cho tép vào chảo không dầu rang cho ráo nước và chuyển màu hồng cam.", "Thêm 1 muỗng mỡ heo (hoặc dầu ăn), hành tím phi thơm đảo đều cùng tép.", "Cho khế chua vào đảo chung, nêm nước mắm và đường cho vị mặn ngọt chua cân bằng, rắc lá chanh thái chỉ."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('56d40b0d-96ff-5a45-a64f-12610d27aa30', 'Nộm dưa chuột thịt bò', 'rau', 4, '["Thịt bò thăn thái lát mỏng, xào nhanh trên lửa lớn vừa chín tới với chút tỏi.", "Dưa chuột rửa sạch bỏ bớt ruột, thái lát xéo ngâm chút muối đường 10 phút rồi vắt nhẹ ráo nước.", "Cà rốt bào sợi, rau kinh giới mùi tàu thái khúc nhỏ.", "Trộn dưa chuột, cà rốt với thịt bò xào, rưới nước mắm chua ngọt tỏi ớt trộn đều.", "Rắc đậu phộng rang giã dập lên trên đĩa nộm dòn mát."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('581d6753-48a1-5133-897a-1a1b9e819035', 'Nộm hoa chuối tai heo', 'rau', 4, '["Tai heo bóp muối chanh luộc chín giòn, ngâm nước đá rồi thái lát thật mỏng.", "Hoa chuối thái mỏng ngâm ngay vào âu nước có pha nước cốt chanh và muối để không bị thâm đen.", "Cà rốt bào sợi, giá đỗ rửa sạch, rau kinh giới húng quế thái nhỏ.", "Pha nước mắm chua ngọt tỏi ớt đậm đà.", "Vắt ráo hoa chuối, trộn đều cùng tai heo giòn sần sật, các loại rau thơm và nước sốt nộm, rắc lạc rang."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('59b1d40e-aab7-5a34-8644-2b4d747a1164', 'Cá bống kho tiêu', 'man', 4, '["Cá bống làm sạch ruột, đánh sạch vảy, xóc với muối hạt rồi rửa sạch, để ráo nước.", "Ướp cá với nước mắm ngon, tiêu xay thật nhiều, đường, hành tỏi băm trong 30 phút.", "Thắng nước màu đường trong nồi đất cho vàng cánh gián, cho cá bống vào đun sôi lăn tăn.", "Không đảo cá để tránh vỡ nát, thỉnh thoảng lắc nhẹ nồi cho ngấm đều gia vị.", "Kho lửa nhỏ liu riu đến khi thịt cá săn đanh lại, nước kho cạn sánh bóng, rắc thêm ớt hiểm và tiêu sọ."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('5a0ef719-61af-5283-b8c2-ea41c7df1b72', 'Bò hầm rượu vang kiểu Pháp (Boeuf Bourguignon)', 'man', 4, '["Nạm bò hoặc bắp bò cắt khối vuông 3.5cm, ướp muối tiêu và chút rượu vang 20 phút.", "Áp chảo thịt bò trên nồi gang lửa lớn cho xém vàng các mặt rồi gắp ra.", "Xào hành tây, cà rốt, nấm hương và tỏi băm thơm nức.", "Trút thịt bò trở lại nồi, đổ 200ml rượu vang đỏ và 500ml nước hầm xương ngập mặt thịt.", "Hầm lửa nhỏ liu riu trong 50 phút đến khi thịt bò mềm tan trong miệng, nước sốt rượu vang nâu sánh đậm đà."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('5b16678d-91f2-5c2d-9909-36bb5264c1d8', 'Canh rong biển truyền thống Hàn Quốc (Miyeokguk)', 'canh', 4, '["Rong biển khô ngâm nước lạnh 15 phút cho nở to, vắt ráo cắt khúc 4cm.", "Thịt bò thái mỏng ướp tỏi băm, nước tương và 1 muỗng dầu mè thơm.", "Xào thịt bò với dầu mè trong nồi đến khi săn chín.", "Cho rong biển vào xào chung cùng thịt bò 2 phút cho rong biển ngấm đượm dầu mè.", "Đổ 1 lít nước lọc vào đun sôi, hạ nhỏ lửa đun liu riu 20 phút cho nước canh ngọt thanh đậm đà, nêm nước tương Hàn Quốc."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('5f6af644-157a-5e0f-a9bd-b2883ae7bac9', 'Cá ba sa kho nghệ', 'man', 4, '["Cá ba sa cắt khúc, chà muối gừng khử mùi tanh, để ráo nước.", "Củ nghệ tươi gọt vỏ giã nhuyễn lấy cả nước lẫn xác nghệ.", "Ướp cá với nghệ giã, hành tím băm, nước mắm, đường, hạt nêm và ớt đập dập trong 25 phút.", "Bắc nồi lên bếp xào săn cá trên lửa lớn để cá thấm màu vàng tươi của nghệ.", "Thêm 80ml nước sôi, đậy vung hạ lửa nhỏ kho liu riu 25 phút cho cá ngấm vị đậm đà và nước sánh lại."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('60152909-c073-5c4e-aa02-37820204329d', 'Bông bí xào tỏi', 'rau', 4, '["Bông bí tước sạch phần xơ ở cuống, ngắt bỏ nhụy đắng bên trong hoa, rửa nhẹ nhàng để không dập nát.", "Phi thơm thật nhiều tỏi đập dập với dầu ăn trên chảo lửa lớn.", "Trút bông bí vào đảo nhanh tay trên lửa lớn 2 phút.", "Nêm nước mắm hạt nêm vừa ăn, khi cánh hoa vừa mềm chín giòn ngọt thì tắt bếp dọn ra đĩa."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('6360bdf3-f1bf-5196-a119-cce09a15b9ef', 'Bánh kếp kim chi hải sản Hàn Quốc (Pajeon)', 'man', 4, '["Mực và tôm bóc vỏ cắt miếng nhỏ, kim chi cải thảo thái nhỏ vắt nhẹ ráo nước.", "Hành lá rửa sạch cắt khúc dài 6cm.", "Pha bột bánh: bột mì, bột bắp, 1 quả trứng gà, nước kim chi khuấy tan thành hỗn hợp sánh sệt vừa phải.", "Trộn hải sản, kim chi và hành lá vào tô bột.", "Đun nóng chảo dầu, múc bột trải đều thành lớp bánh mỏng, chiên lửa vừa đến khi hai mặt vàng ruộm giòn tan chấm nước tương ớt."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('63c54fb2-ba4c-5015-ba6e-3a77e503e7a7', 'Canh chua đầu cá hồi măng chua', 'canh', 4, '["Đầu cá hồi chặt miếng vừa ăn, rửa sạch bóp rượu gừng khử tanh, chiên sơ cho săn thịt.", "Măng chua tước sợi luộc qua một lần nước sôi rửa sạch.", "Cà chua bổ múi cau, dứa thái lát, me lọc lấy nước cốt.", "Phi thơm hành tỏi xào cà chua dứa măng chua cho ngấm vị.", "Đổ nước sôi vào nấu cùng đầu cá hồi trong 12 phút, nêm nước mắm đường cốt me chua cay đậm đà, rắc thì là hành lá."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('6460a33a-daf0-596f-aa48-517adf1f7b30', 'Canh sườn nấu sấu', 'canh', 4, '["Sườn non chặt khúc 3cm, chần qua nước sôi rửa sạch bọt bẩn.", "Sấu cạo vỏ rửa sạch, khía vài đường quanh quả.", "Cà chua bổ múi cau, hành lá và rau mùi tàu thái nhỏ.", "Cho sườn vào nồi cùng 1.2 lít nước, đun sôi rồi vớt bọt, hầm lửa nhỏ 25 phút cho sườn mềm ngọt nước.", "Thả sấu và cà chua vào nấu thêm 10 phút, dầm sấu lấy vị chua thanh mát dịu, nêm nước mắm rắc hành mùi tàu."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('661ae676-2893-5894-b4ab-87572ca39b31', 'Thịt kho tàu với trứng', 'man', 4, '["Thịt ba chỉ cạo sạch lông, rửa với nước muối loãng, cắt miếng vuông khoảng 3-4cm.", "Ướp thịt với hành tím băm, tỏi băm, 2 muỗng nước mắm, 1 muỗng đường, tiêu trong 30 phút.", "Luộc chín 4 quả trứng vịt, bóc sạch vỏ.", "Thắng nước màu đường caramen trên chảo, cho thịt vào đảo săn đều màu.", "Đổ nước dừa tươi vào ngập mặt thịt, đun sôi vớt bọt, hạ nhỏ lửa kho liu riu 30 phút.", "Cho trứng vào kho cùng thêm 20 phút đến khi thịt mềm rục, nước sánh vàng óng thì tắt bếp."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('6926a9aa-c3cf-59e0-ab24-afeb00d560d0', 'Mì Ý sốt thịt bò băm (Spaghetti Bolognese)', 'man', 4, '["Luộc mì Spaghetti trong nước sôi có muối 8-10 phút cho chín tới (al dente), vớt ra xóc chút dầu oliu.", "Hành tây, cà rốt, cần tây băm nhỏ hạt lựu, tỏi băm nhuyễn.", "Phi thơm tỏi và hành tây với dầu oliu, cho thịt bò băm vào xào săn trên lửa lớn.", "Đổ cà chua xay nhuyễn, lá oregano và húng quế khô vào nồi sốt, nêm muối tiêu và đun nhỏ lửa om 20 phút cho sốt sánh đậm đà.", "Bày mì Ý ra đĩa, chan sốt bò băm nóng hổi lên trên, rắc phô mai Parmesan bào vụn."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('695455a6-39e3-5b01-abf5-ba1d698689e9', 'Măng tây xào tỏi bơ', 'rau', 4, '["Măng tây cắt bỏ phần gốc già cứng, rửa sạch, cắt khúc dài 5cm.", "Chần măng tây qua nước sôi có chút muối 30 giây rồi ngâm nước đá lạnh cho giòn xanh.", "Làm nóng chảo, cho 1 muỗng dầu ăn và 1 muỗng bơ lạt vào đun chảy.", "Phi thơm tỏi băm trên lửa vừa đến khi dậy mùi thơm nức.", "Trút măng tây vào xào nhanh trên lửa lớn 2 phút, nêm chút muối tiêu rồi tắt bếp."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('6a01a463-5a01-5771-b94a-39ab5ff07a26', 'Bò kho sả gừng nước dừa', 'man', 4, '["Nạm bò hoặc bắp bò cắt miếng vuông 3cm, chần qua nước gừng nóng khử mùi.", "Ướp bò với gói gia vị bò kho, sả băm, gừng, tỏi, nước mắm, đường trong 30 phút.", "Phi thơm hành tỏi và sả đập dập, trút thịt bò vào xào săn trên lửa lớn.", "Đổ nước dừa tươi ngập mặt thịt, đun sôi rồi hạ nhỏ lửa hầm liu riu 45 phút cho bò mềm.", "Cho cà rốt cắt khúc vào hầm thêm 15 phút, nước sốt sánh đậm đà, ăn cùng bánh mì hoặc cơm."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('6da3f756-3a2a-51d7-89b4-0a0e91fed919', 'Canh nấm hạt sen sườn non', 'canh', 4, '["Sườn non chặt khúc chần nước sôi rửa sạch bọt bẩn.", "Hạt sen tươi thông tâm rửa sạch, nấm hương nấm rơm ngâm rửa sạch cắt đôi.", "Hầm sườn non với 1.2 lít nước trên lửa vừa trong 25 phút.", "Thả hạt sen và nấm vào hầm chung thêm 15 phút đến khi hạt sen bở mềm bùi ngọt nước.", "Nêm hạt nêm nước mắm vừa ăn, rắc hành ngò tiêu xay bổ dưỡng thơm dịu."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('6fcf9e1f-7f02-5c01-8a58-590469911d12', 'Canh kim chi đậu hũ thịt ba chỉ', 'canh', 4, '["Thịt ba chỉ thái miếng mỏng vừa ăn.", "Kim chi cải thảo cắt khúc 3cm, giữ lại cả nước muối kim chi chua cay.", "Đậu hũ trắng cắt miếng vuông dày 1.5cm.", "Xào thịt ba chỉ trên nồi cho xém cạnh tiết bớt mỡ, cho tỏi băm và kim chi vào đảo đều 3 phút.", "Đổ 900ml nước lọc và nước kim chi vào đun sôi, hạ nhỏ lửa đun 10 phút cho vị chua cay ngấm đều.", "Thả đậu hũ non vào nấu sôi thêm 3 phút, nêm chút hạt nêm đường, rắc hành lá cắt khúc."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('70792543-d5c9-56fe-b83e-d8e9cf24ac04', 'Đậu hũ sốt cà chua', 'rau', 4, '["Đậu hũ trắng cắt miếng vuông 3cm, chiên vàng đều các mặt trên chảo dầu nóng.", "Cà chua rửa sạch, băm nhuyễn hoặc thái múi cau.", "Phi thơm hành tím băm, trút cà chua vào xào nhừ thành nước sốt sệt đỏ au.", "Nêm nước mắm, đường, chút hạt nêm cho vừa miệng.", "Cho đậu hũ chiên vào sốt cà chua, đun nhỏ lửa 5-7 phút cho ngấm gia vị, rắc hành lá cắt nhỏ."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('70cc92f4-ac36-50f6-92ff-b2965332b103', 'Canh hến nấu rau muống', 'canh', 4, '["Hến tươi ngâm nước vo gạo 1 tiếng nhả cát, luộc sôi với nước và chút muối đến khi mở miệng.", "Đãi lấy phần ruột hến, gạn lấy nước luộc hến trong không cặn cát.", "Rau muống nhặt khúc non rửa sạch để ráo.", "Phi thơm hành tím, xào săn ruột hến với nước mắm tiêu rồi trút nước luộc hến vào đun sôi.", "Thả rau muống vào nấu sôi trên lửa lớn 2-3 phút cho rau chín giòn xanh, rắc chút gừng đập dập thơm ấm."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('7125a101-2b6c-556a-8944-7c9a09cbd4c2', 'Bò cuộn nấm kim châm áp chảo', 'man', 4, '["Thịt bò ba chỉ thái dải dài mỏng chuyên dùng cuộn nấm.", "Nấm kim châm cắt gốc, rửa sạch chia thành các phần nhỏ.", "Trải dải thịt bò ra, đặt nấm kim châm vào giữa rồi cuộn tròn chặt tay.", "Pha nước sốt: 2 muỗng nước tương, 1 muỗng dầu hào, 1 muỗng đường, 1/2 muỗng tiêu, 3 muỗng nước.", "Áp chảo các cuộn thịt bò trên chảo nóng cho vàng xém các mặt, đổ nước sốt vào đảo đều 2 phút cho bóng đẹp rồi tắt bếp."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('74bceee7-cc89-534c-8fc8-02e25477d410', 'Đậu hũ nhồi thịt sốt cà chua', 'man', 4, '["Đậu hũ trắng cắt miếng vuông 5cm, khoét nhẹ một phần ruột đậu ở giữa.", "Thịt nạc xay trộn đều cùng nấm mèo băm nhỏ, hành tím, chút ruột đậu, nước mắm, tiêu.", "Nhồi phần nhân thịt vào giữa từng miếng đậu hũ.", "Chiên sơ mặt nhồi thịt trên chảo dầu nóng cho thịt săn chắc và không bị rơi ra.", "Cà chua băm nhuyễn xào thành sốt, xếp đậu hũ vào om nhỏ lửa 15 phút cho ngấm sốt, rắc hành ngò."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('74dc8d98-4bb2-59ae-bc86-50c90aa11ecd', 'Bí đao xào tỏi', 'rau', 4, '["Bí đao gọt vỏ, bổ đôi bỏ phần ruột xốp bên trong, thái lát mỏng vừa ăn.", "Tỏi bóc vỏ đập dập thơm.", "Làm nóng chảo với dầu ăn, phi thơm tỏi đập dập trên lửa vừa.", "Cho bí đao vào xào trên lửa lớn, nêm chút hạt nêm nước mắm đảo đều tay.", "Xào khoảng 3 phút đến khi miếng bí vừa trong chín giòn ngọt thanh, rắc hành lá tiêu xay rồi tắt bếp."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('750a1cc6-b5b7-50a2-95bf-d827611e4652', 'Cá hồi đút lò phô mai', 'man', 4, '["Cá hồi phi lê rửa sạch thấm khô, ướp chút muối tiêu và dầu oliu.", "Pha hỗn hợp phủ mặt cá: phô mai bào, tỏi băm, rau mùi tây băm nhuyễn và chút sốt mayonnaise.", "Phết đều lớp sốt phô mai lên trên từng miếng cá hồi.", "Cho vào lò nướng hoặc nồi chiên không dầu ở 180°C trong 12-14 phút.", "Lớp phô mai chảy vàng óng xém mặt thơm béo ngậy quyện cùng thịt cá hồi ngọt mềm mọng nước."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('7cc3d713-b931-5054-9d4a-ca842196d872', 'Vịt om sấu chua thanh', 'man', 4, '["Vịt làm sạch, chặt miếng vừa ăn, chần qua nước gừng nóng khử mùi.", "Sấu cạo vỏ rửa sạch, khía chữ thập quanh quả.", "Ướp vịt với hành, tỏi, sả băm, hạt nêm, nước mắm trong 20 phút.", "Xào săn thịt vịt với sả hành, đổ nước dừa hoặc nước lọc ngập thịt và thả sấu vào nấu sôi.", "Hạ lửa om 25 phút cho vịt mềm, dầm sấu lấy vị chua thanh dịu, thả rau rút và mùi tàu cắt khúc rồi tắt bếp."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('7d9e5a7d-85e6-5d3a-a266-bef14b6904ab', 'Tôm xào bông cải', 'man', 4, '["Tôm sú bóc vỏ, bỏ chỉ đen trên lưng, rửa sạch thấm khô.", "Bông cải xanh và trắng cắt miếng vừa ăn, chần nhanh qua nước sôi có chút muối rồi ngâm nước lạnh.", "Cà rốt tỉa hoa thái lát.", "Phi thơm tỏi trên chảo lửa lớn, cho tôm vào xào săn chín tới rồi múc ra đĩa.", "Cho bông cải và cà rốt vào xào nhanh tay, nêm hạt nêm dầu hào, trút tôm vào đảo đều 1 phút rắc tiêu."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('89ce3140-3132-5379-8f85-403abc8357a4', 'Trứng ốp la xúc xích đậu hầm sốt cà (English Breakfast)', 'man', 4, '["Xúc xích khía nhẹ thân, áp chảo vàng đều các mặt trên chảo bơ.", "Thịt xông khói áp chảo giòn thơm.", "Cà chua bổ đôi áp chảo xém cạnh ngọt thơm.", "Ốp la 4 quả trứng gà giữ lòng đào béo ngậy.", "Hâm nóng đậu trắng hầm sốt cà chua, bày toàn bộ ra đĩa lớn ăn kèm bánh mì nướng giòn."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('8a311722-ff19-5061-96b9-01a0d4a5c8e9', 'Gỏi gà xé phay bắp cải', 'rau', 4, '["Thịt ức hoặc đùi gà luộc chín tới, xé sợi vừa ăn.", "Bắp cải bào sợi mỏng rửa sạch ngâm nước đá cho giòn ráo.", "Hành tây thái mỏng ngâm giấm đường khử hăng, rau răm thái nhỏ.", "Pha nước sốt trộn: nước cốt chanh, đường, nước mắm, tỏi ớt băm nhuyễn và tiêu xay.", "Trộn đều bắp cải, thịt gà xé, hành tây với nước sốt, rắc đậu phộng rang và hành phi giòn."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('8a4e1f47-3d39-53cb-9fc5-10cc919a7526', 'Thịt heo kho quẹt tóp mỡ', 'man', 4, '["Mỡ phần heo cắt hạt lựu, thắng trên chảo nhỏ lửa lấy tóp mỡ giòn vàng, vớt ra để riêng.", "Tôm khô ngâm nước ấm 15 phút cho mềm, rửa sạch để ráo.", "Pha hỗn hợp: 5 muỗng nước mắm, 4 muỗng đường, 3 muỗng nước lọc, tiêu sọ đập dập.", "Phi thơm hành tỏi băm với 1 muỗng mỡ heo trong tộ đất, cho tôm khô vào xào săn.", "Đổ hỗn hợp nước mắm vào đun sôi, hạ lửa nhỏ đun liu riu đến khi keo lại sền sệt.", "Trút tóp mỡ, ớt hiểm, tiêu xanh vào đảo đều 2 phút rồi tắt bếp, dùng chấm rau củ luộc."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('8c3d5323-e7fb-5169-b87a-5ae409853b6c', 'Canh sườn hầm khoai tây cà rốt', 'canh', 4, '["Sườn heo chặt khúc 3cm chần nước sôi rửa sạch.", "Khoai tây, cà rốt gọt vỏ cắt khối vuông quân cờ vừa ăn.", "Cho sườn vào nồi hầm với 1.2 lít nước trên lửa vừa trong 25 phút vớt sạch bọt cho nước trong.", "Cho cà rốt và khoai tây vào hầm thêm 15 phút đến khi củ quả chín mềm bở bùi ngọt lịm.", "Nêm nước mắm hạt nêm vừa miệng, rắc hành lá mùi tàu thái nhỏ và tiêu xay thơm nồng."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('8f7a7b22-af3c-53a4-a7fb-6c1d4b8da421', 'Nấm đùi gà xào xì dầu', 'rau', 4, '["Nấm đùi gà cắt gốc, rửa sạch, thái lát dày 0.5cm hoặc cắt quân cờ.", "Pha sốt xì dầu: 2 muỗng nước tương ngon, 1 muỗng dầu hào, 1/2 muỗng đường, tiêu.", "Phi thơm tỏi băm với dầu ăn trên chảo nóng.", "Cho nấm đùi gà vào xào trên lửa lớn cho nấm săn lại và tiết nước ngọt.", "Đổ sốt xì dầu vào đảo đều 3 phút cho nấm ngấm vị đậm đà nâu bóng, rắc hành lá cắt khúc."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('91536705-28ee-5fd3-9b2e-5849a8dfa69d', 'Bắp cải xào cà chua', 'rau', 4, '["Bắp cải rửa sạch, thái sợi dày khoảng 1cm.", "Cà chua rửa sạch bổ múi cau, hành lá cắt khúc.", "Phi thơm hành tím băm trên chảo dầu nóng, cho cà chua vào đảo nhuyễn tạo màu.", "Trút bắp cải vào xào trên lửa lớn, nêm chút nước mắm và hạt nêm.", "Xào đến khi bắp cải chín mềm ngọt nhưng vẫn giữ được độ tươi giòn, rắc hành lá tiêu xay."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('93c4ea70-665c-5080-9cb5-156bea12ae04', 'Mực xào cần tỏi', 'man', 4, '["Mực tươi làm sạch, thái khoanh hoặc khía hoa, ướp chút gừng băm và tiêu.", "Cần tây, tỏi tây cắt khúc, hành tây bổ múi cau.", "Bắc chảo lên bếp lửa lớn, phi thơm tỏi đập dập, trút mực vào đảo nhanh tay 1-2 phút cho mực săn giòn rồi vớt ra.", "Tiếp tục xào cần tây, tỏi tây, hành tây cho vừa chín tới.", "Đổ mực vào đảo lại cùng rau trong 30 giây, nêm dầu hào và tiêu thơm rồi tắt bếp."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('93ece9d2-a1de-5326-83df-946cf3090753', 'Bò bít tết sốt tiêu đen (Beef Steak)', 'man', 4, '["Thịt thăn bò dày 2.5cm thấm khô nước, ướp muối biển, tiêu đen đập dập và dầu oliu 15 phút.", "Đun nóng chảo gang trên lửa lớn thật nóng, cho bít tết vào áp chảo 2-3 phút mỗi mặt.", "Cho bơ lạt, tỏi đập dập và nhánh hương thảo vào chảo, rưới bơ nóng liên tục lên miếng thịt để tạo lớp vỏ nâu giòn mọng nước.", "Gắp thịt ra đĩa để nghỉ 5 phút giữ trọn độ ngọt mọng bên trong.", "Pha sốt tiêu đen từ bơ, tiêu đen sọ giã dập, dầu hào, nước tương đun sôi sánh, rưới lên bít tết dùng kèm khoai tây chiên."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('96fcd924-9a95-50cc-9616-251bd48012a2', 'Canh ngao nấu chua thì là', 'canh', 4, '["Ngao (nghêu) ngâm nước có cắt vài lát ớt 1 tiếng cho nhả hết cát, rửa sạch vỏ ngoài.", "Cho ngao vào nồi với 1 lít nước đun sôi cho ngao mở miệng, vớt ngao ra nhặt lấy ruột thịt, gạn nước luộc trong.", "Cà chua bổ múi cau, dứa thái lát, khế chua thái lát mỏng, hành lá và thì là cắt khúc.", "Phi thơm hành tím, xào cà chua rồi đổ nước luộc ngao vào đun sôi cùng dứa và khế.", "Thả ruột ngao vào đun sôi lại, nêm nước mắm vừa ăn, tắt bếp rắc hành lá thì là thơm ngát."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('98f016c0-6e0d-5371-ac82-ff119f01b579', 'Lòng gà xào mướp hương', 'man', 4, '["Lòng mề gà bóp muối và chanh thật kỹ khử mùi hôi, rửa sạch, thái miếng vừa ăn.", "Ướp lòng gà với hành tím băm, hạt nêm, nước mắm và tiêu trong 15 phút.", "Mướp hương gọt vỏ, bổ đôi thái vát dày 1cm, hành lá cắt khúc.", "Phi thơm hành tím trên chảo dầu nóng, trút lòng gà vào xào chín săn trên lửa lớn rồi múc ra đĩa.", "Cho mướp vào xào nhanh trên lửa lớn vừa chín tới thì trút lòng gà vào đảo đều, rắc hành hoa tiêu xay."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('9ab7a379-351b-5e16-9304-fb265eaf006d', 'Sườn non rim mặn ngọt', 'man', 4, '["Sườn non chặt khúc vừa ăn, chần qua nước sôi 2 phút rồi rửa sạch, để ráo.", "Ướp sườn với hành tỏi băm, 1 muỗng nước mắm, 1 muỗng hạt nêm, tiêu trong 15 phút.", "Chiên sườn trên chảo với ít dầu đến khi vàng xém các mặt.", "Pha nước sốt: 2 muỗng nước mắm, 1.5 muỗng đường, 1 muỗng giấm, 3 muỗng nước lọc.", "Đổ nước sốt vào chảo sườn, đậy nắp đun lửa nhỏ đến khi sốt keo lại bám đều quanh miếng sườn."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('9adfb7a0-806e-5c9b-9cac-cf71ba06f1b2', 'Thịt heo xào kim chi cay Hàn Quốc', 'man', 4, '["Thịt ba chỉ thái lát mỏng vừa ăn.", "Kim chi cải thảo chua cay cắt khúc ngắn 3cm.", "Hành tây thái múi cau, hành boa-rô cắt xéo.", "Xào thịt ba chỉ trên chảo lửa lớn cho xém cạnh tiết bớt mỡ, cho tỏi băm và kim chi vào đảo đều 4 phút.", "Nêm 1 muỗng tương ớt Gochujang, 1 muỗng nước tương, 1 muỗng đường đảo đều tay, rắc hành boa-rô và mè rang."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('9b7109d6-2c15-57d8-8ae6-f84ee0218aff', 'Canh nghêu nấu hoa thiên lý', 'canh', 4, '["Nghêu ngâm ớt rửa sạch, luộc sôi với nước cho mở miệng, tách lấy ruột và gạn nước luộc trong.", "Hoa thiên lý nhặt rửa sạch ngâm nước muối loãng để ráo.", "Phi thơm hành tím xào sơ ruột nghêu với nước mắm tiêu.", "Đổ nước luộc nghêu vào đun sôi bùng, thả hoa thiên lý vào nấu trong 1-2 phút cho vừa chín tới giữ độ giòn thơm ngọt mát.", "Tắt bếp nêm nếm lại rồi múc ra tô lớn thưởng thức."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('9cb50e80-739f-5766-b998-c1fff3ae08d0', 'Cải thìa sốt dầu hào', 'rau', 4, '["Cải thìa cắt đôi dọc theo thân, rửa sạch bùn đất trong các bẹ lá.", "Chần cải thìa trong nước sôi có chút muối và vài giọt dầu ăn 1 phút để cải bóng xanh giòn.", "Vớt cải xếp ngay ngắn ra đĩa tròn.", "Pha nước sốt: 2 muỗng dầu hào, 1 muỗng nước tương, 1 muỗng đường, 3 muỗng nước lọc, chút bột bắp.", "Phi thơm tỏi băm, đổ sốt vào đun sôi sánh lại rồi rưới đều lên đĩa cải thìa luộc."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('a1fd3434-5f3c-57dc-8018-b3aa8984f456', 'Canh mướp hương nấu tôm khô', 'canh', 4, '["Tôm khô ngâm nước ấm 15 phút cho mềm, giã hơi dập.", "Mướp hương gọt vỏ, bổ đôi thái vát xéo dày 1.5cm.", "Phi thơm hành tím, cho tôm khô vào đảo săn dậy mùi thơm đậm đà.", "Đổ 1 lít nước vào đun sôi 5 phút cho tôm tiết nước ngọt lịm.", "Thả mướp hương vào đun sôi bùng trong 2 phút đến khi mướp vừa chín tới thơm lừng, nêm nước mắm rắc hành ngò."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('a52e6390-7513-54ab-81bb-66399a30c6de', 'Canh cải cúc nấu thịt băm', 'canh', 4, '["Rau cải cúc (tần ô) nhặt gốc rửa sạch, cắt đôi hoặc để nguyên ngọn.", "Thịt nạc băm ướp chút hạt nêm và hành tím băm nhỏ.", "Phi thơm hành tím, xào săn thịt băm rồi đổ 1 lít nước vào đun sôi bùng.", "Thả rau cải cúc vào dìm ngập nước sôi, nấu nhanh trong 1-2 phút vì cải cúc rất nhanh chín.", "Nêm nước mắm ngon và tiêu thơm rồi tắt bếp ngay để cải cúc giữ vị ngăm ngọt thơm nồng."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('aa842747-d961-5118-85a3-709b6d65f746', 'Tôm rim mặn ngọt', 'man', 4, '["Tôm sú hoặc tôm đất cắt bỏ đầu nhọn, râu và chân tôm, giữ lại vỏ để khi rim tôm giòn bóng.", "Rửa sạch tôm, để ráo, ướp với hành tím băm, 1/2 muỗng hạt nêm, tiêu trong 10 phút.", "Làm nóng chảo với dầu ăn, phi thơm hành tỏi băm rồi cho tôm vào đảo nhanh tay trên lửa lớn đến khi tôm đổi màu đỏ.", "Pha nước sốt: 2 muỗng nước mắm, 1.5 muỗng đường, 1/2 muỗng tiêu.", "Đổ sốt vào chảo tôm, đảo đều tay trên lửa vừa đến khi nước sốt keo lại bám óng ánh quanh thân tôm."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('ae25ff95-2cca-5d25-9926-a454ccf44e20', 'Giá đỗ xào huyết heo', 'rau', 4, '["Giá đỗ nhặt bỏ rễ sâu, rửa sạch để ráo nước.", "Huyết heo luộc chín, cắt khối vuông quân cờ vừa ăn.", "Hẹ hoặc hành lá rửa sạch cắt khúc dài 4cm.", "Phi thơm hành tỏi băm trên chảo dầu nóng, cho huyết heo vào đảo nhẹ tay tránh vỡ.", "Trút giá đỗ và hẹ vào đảo nhanh trên lửa lớn 1 phút, nêm nước mắm tiêu rồi tắt bếp ngay giữ độ giòn."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('ae2766ff-1462-59a4-a01e-7e6ab3633476', 'Canh rau má nấu thịt nạc', 'canh', 4, '["Rau má nhặt bỏ lá vàng rễ sâu, rửa sạch nhiều lần, ngâm nước muối loãng rồi để ráo.", "Thịt heo nạc băm nhỏ ướp chút hành tím, nước mắm, tiêu.", "Phi thơm hành tím trong nồi xào chín săn thịt băm.", "Đổ 1 lít nước vào đun sôi bùng, thả rau má vào dìm ngập nước nấu trong 2 phút.", "Nêm nước mắm hạt nêm vừa vị thanh mát giải nhiệt, tắt bếp dọn ăn nóng hoặc nguội."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('b06440e1-84a0-5007-b9b8-9d03a0a8f15a', 'Chả lụa rim nước mắm tiêu', 'man', 4, '["Chả lụa (giò lụa) cắt miếng tam giác hoặc vuông dày khoảng 1cm.", "Chiên sơ các mặt chả lụa trên chảo dầu nóng cho vàng nhẹ và phồng giòn.", "Pha sốt rim: 2 muỗng nước mắm, 1 muỗng đường, 1/2 muỗng tương ớt, 1 muỗng tiêu xay, 3 muỗng nước.", "Phi thơm tỏi băm và ớt cắt lát, trút nước sốt vào đun sôi.", "Cho chả lụa vào đảo đều tay trên lửa nhỏ đến khi sốt keo óng ả bám quanh miếng chả."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('b4825e54-2708-519b-b7e9-86d8164fd901', 'Thịt heo kho tiêu', 'man', 4, '["Thịt nạc dăm hoặc ba chỉ thái miếng vuông nhỏ vừa ăn.", "Ướp thịt với nước mắm ngon, đường, hành tỏi băm và thật nhiều tiêu xay trong 20 phút.", "Thắng nước màu đường trong nồi đất hoặc nồi dày, trút thịt vào xào săn trên lửa lớn.", "Hạ nhỏ lửa, đậy vung kho liu riu không thêm nước để thịt thấm gia vị và tiết nước sốt đậm đà.", "Kho khoảng 15 phút đến khi nước cạn sánh sệt, rắc thêm ớt và tiêu hạt rồi tắt bếp."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('b4dd6cfe-49e6-576c-8eed-8564f603187b', 'Rau dền luộc chấm mắm cá', 'rau', 4, '["Rau dền đỏ và dền cơm nhặt lấy đọt non, rửa sạch ngâm nước muối loãng 5 phút.", "Đun sôi nồi nước lớn với 1/2 muỗng muối hạt trên lửa lớn.", "Thả rau dền vào dìm ngập nước, luộc khoảng 3 phút cho rau mềm ngọt vừa tới.", "Vớt rau ra đĩa sâu lòng, phần nước luộc màu hồng tím ngọt mát để riêng làm canh.", "Chấm rau dền cùng chén nước mắm ngon dầm trứng luộc hoặc nước mắm cá cơm tỏi ớt."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('b6f913f6-95be-5945-b2b4-b7d0430f31e5', 'Khổ qua xào trứng', 'rau', 4, '["Khổ qua (mướp đắng) rửa sạch, bổ đôi nạo sạch ruột trắng, thái lát mỏng xéo.", "Ngâm khổ qua vào âu nước đá lạnh 10 phút để giảm vị đắng và tăng độ giòn.", "Đập 3 quả trứng gà vào chén, nêm chút hạt nêm tiêu đánh tan.", "Phi thơm hành tím trên chảo dầu nóng, cho khổ qua vào xào trên lửa lớn 2 phút vừa chín tới.", "Rưới trứng vào chảo, đảo đều tay nhẹ nhàng đến khi trứng chín bám quanh miếng khổ qua rồi tắt bếp."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('bdd9f587-25f8-53f8-b8f6-8a58cdb98572', 'Thịt heo chiên xù kiểu Nhật (Tonkatsu)', 'man', 4, '["Thịt thăn heo dày 1.5cm, dùng búa dần thịt đập nhẹ hai mặt cho mềm thớ, ướp muối tiêu.", "Chuẩn bị 3 đĩa: bột mì, trứng gà đánh tan, bột chiên xù (panko).", "Lăn miếng thịt lần lượt qua bột mì, nhúng ngập trứng rồi áo đều lớp bột chiên xù bên ngoài.", "Thả thịt vào chảo dầu nóng 170°C chiên ngập dầu khoảng 5-6 phút đến khi vỏ ngoài vàng ruộm giòn tan.", "Gắp thịt ra để ráo dầu, cắt thành từng thanh dài, dọn kèm bắp cải thái sợi mỏng và sốt Tonkatsu mè rang."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('bf5b05b9-2a11-5c2a-bd5c-d5e6f5711d63', 'Cá hồi áp chảo sốt bơ chanh tỏi', 'man', 4, '["Phi lê cá hồi rửa sạch thấm khô nước, ướp muối, tiêu và chút dầu oliu 10 phút.", "Làm nóng chảo với chút dầu oliu, đặt mặt da cá xuống áp chảo lửa vừa 4 phút cho da vàng giòn rụm.", "Lật mặt thịt cá áp chảo thêm 2 phút cho cá chín tới mọng nước rồi gắp ra đĩa.", "Hạ nhỏ lửa, cho bơ lạt vào chảo phi thơm tỏi băm, vắt nước cốt chanh vàng và chút ngò tây thái nhỏ khuấy đều.", "Rưới sốt bơ chanh tỏi thơm béo ngậy lên miếng cá hồi, ăn kèm măng tây hoặc khoai tây nghiền."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('c09b3318-eb04-55b6-a7c6-11d5a89ef975', 'Cá điêu hồng chiên giòn', 'man', 4, '["Cá điêu hồng đánh sạch vảy, khía xéo vài đường trên mình cá, để thật ráo nước.", "Xát nhẹ một lớp muối mỏng quanh mình cá.", "Đun nóng chảo ngập dầu ăn, thả cá vào chiên trên lửa vừa đến khi một mặt vàng giòn rồi mới lật.", "Chiên vàng giòn đều cả hai mặt, vớt cá ra đĩa có lót giấy thấm dầu.", "Pha nước mắm tỏi ớt chanh chua ngọt đậm đà để chấm cùng, ăn kèm rau sống bánh tráng."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('c158e87e-3658-54eb-b9ed-e96739f4e138', 'Mực xào chua ngọt', 'man', 4, '["Mực ống làm sạch, khía vảy rồng rồi cắt miếng vuông vừa ăn, chần sơ qua nước sôi với rượu gừng.", "Dưa leo, cà chua, dứa (thơm), hành tây, cần tây cắt miếng vừa ăn.", "Phi thơm tỏi trên chảo lửa lớn, xào mực nhanh tay 1 phút rồi trút ra đĩa.", "Cho dứa, cà chua, dưa leo, hành tây vào xào trên lửa lớn, nêm nước mắm, đường, giấm cho vừa vị chua ngọt.", "Trút mực và cần tây vào đảo đều nhanh 1 phút nữa, rắc tiêu rồi tắt bếp."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('c59030cd-5026-5413-9e94-ae9be849b89f', 'Củ quả luộc thập cẩm', 'rau', 4, '["Cà rốt, su su, bông cải xanh, đậu bắp, bắp non gọt vỏ rửa sạch, cắt miếng con chì đều nhau.", "Đun sôi nồi nước lớn với 1/2 muỗng muối hạt.", "Cho cà rốt và su su vào luộc trước 3 phút, sau đó cho bông cải, đậu bắp và bắp non vào luộc tiếp 2 phút.", "Vớt toàn bộ củ quả ra đĩa lớn trình bày nhiều màu sắc rực rỡ bắt mắt.", "Chấm kèm kho quẹt tôm thịt hoặc trứng dầm nước mắm ngon."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('c5a6dc55-f899-5d64-b7ed-6eee4775dd98', 'Canh bầu nấu cá lóc', 'canh', 4, '["Cá lóc làm sạch cắt khúc, ướp chút hành tím, nước mắm, tiêu trong 15 phút.", "Bầu non gọt vỏ thái sợi hoặc thái lát mỏng.", "Phi thơm hành tím xào săn cá lóc trên lửa lớn cho cá chắc thịt.", "Đổ 1.1 lít nước sôi vào đun nhỏ lửa 10 phút cho cá chín ngọt nước.", "Thả bầu vào nấu sôi bùng thêm 2 phút đến khi bầu vừa trong mềm, rắc hành ngò tiêu xay thơm nức."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('c6f11b3d-a46c-5e50-ab75-faee43ea838f', 'Ngọn bí xào tỏi', 'rau', 4, '["Ngọn bí nhặt tước sạch xơ bên ngoài cọng và cuống lá, rửa sạch nhiều lần với nước.", "Chần cọng bí qua nước sôi 1 phút rồi thả lá bí vào đảo nhanh vớt ra ngay.", "Làm nóng chảo với nhiều dầu ăn, phi thơm thật nhiều tỏi đập dập.", "Trút ngọn bí vào xào nhanh tay trên lửa thật lớn để rau xanh giòn.", "Nêm nước mắm ngon và chút hạt nêm, đảo đều 1 phút cho ngấm tỏi rồi trút ra đĩa."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('c8299a40-8cb6-5db6-8889-adc26460a273', 'Măng xào tỏi ớt', 'rau', 4, '["Măng củ tươi thái con chì hoặc xé sợi, luộc 2 lần nước sôi mở nắp để thải hết độc đắng, rửa sạch để ráo.", "Tỏi bóc vỏ băm nhỏ, ớt hiểm thái lát mỏng, hành lá cắt khúc.", "Phi thơm tỏi ớt trên chảo dầu nóng dậy mùi thơm cay nồng.", "Trút măng vào xào đều trên lửa lớn, nêm nước mắm, hạt nêm và chút tiêu.", "Đảo đều khoảng 4-5 phút cho măng ngấm đượm gia vị vàng giòn, rắc hành lá rồi tắt bếp."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('c896b9a2-f396-53e8-978d-110ce2da0a64', 'Gà chiên nước mắm giòn da', 'man', 4, '["Cánh gà hoặc đùi gà chặt miếng vừa ăn, khứa nhẹ mặt thịt, ướp chút hạt nêm và tỏi băm.", "Áo gà qua một lớp mỏng bột bắp rồi chiên ngập dầu trên lửa vừa đến khi da gà vàng ươm giòn rụm.", "Pha sốt nước mắm: 2.5 muỗng nước mắm ngon, 2 muỗng đường, 1 muỗng tương ớt, 1 muỗng nước cốt chanh.", "Phi thơm tỏi băm trên chảo, đổ sốt nước mắm vào đun sôi sủi bọt keo lại.", "Trút gà chiên vào đảo thật nhanh tay 1 phút cho sốt bám đều quanh da gà rồi tắt bếp."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('c8ab8243-1eb2-5def-8c49-ee885b42188a', 'Trứng hấp thịt băm nấm mèo', 'man', 4, '["Thịt nạc vai băm nhỏ, nấm mèo và miến ngâm nở thái nhuyễn, hành tím băm nhỏ.", "Đập 3 quả trứng vào tô thịt, chừa lại 1 lòng đỏ để quét mặt bánh.", "Nêm nước mắm, tiêu, hạt nêm trộn đều các nguyên liệu cho sánh mịn.", "Đổ hỗn hợp vào khuôn hoặc tô sứ, cho vào xửng hấp lửa vừa trong 20 phút.", "Đánh tan lòng đỏ trứng còn lại với chút dầu màu điều, quét đều lên mặt trứng rồi hấp tiếp 5 phút không đậy nắp cho mặt vàng đẹp."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('c97e6fda-4aea-5808-9d05-79d254d56b1a', 'Bầu luộc chấm kho quẹt', 'rau', 4, '["Trái bầu non gọt vỏ, rửa sạch, cắt khúc dài 4cm hoặc thái lát dày 1cm.", "Đun sôi nồi nước có chút muối hạt.", "Thả bầu vào luộc lửa vừa khoảng 3 phút đến khi miếng bầu trong lại là chín ngọt.", "Vớt bầu ra đĩa tròn, dùng nóng chấm cùng tộ thịt kho quẹt đậm đà béo ngậy tóp mỡ."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('c9c3abd0-f3aa-5825-b853-1439dc361ee7', 'Thịt ba chỉ luộc chấm mắm tôm', 'man', 4, '["Thịt ba chỉ rửa sạch với muối, cuộn tròn buộc chỉ nếu thích miếng thịt tròn đẹp.", "Đun sôi nồi nước với vài củ hành tím đập dập và nhánh gừng.", "Thả thịt vào luộc khoảng 20-25 phút với lửa vừa đến khi dùng đũa xiên qua không còn nước hồng.", "Vớt thịt ngâm ngay vào âu nước đá lạnh 5 phút để thịt giòn trắng không bị thâm.", "Thái thịt lát mỏng, dọn kèm dưa leo, rau sống và chén mắm tôm đánh sủi bọt với chanh ớt đường."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('c9d3c30f-d51d-565d-a88d-a02f01ee89a0', 'Canh rong biển đậu hũ thịt băm', 'canh', 4, '["Rong biển khô ngâm nước lạnh 10 phút cho nở to, rửa sạch bóp nhẹ ráo nước, cắt khúc vừa ăn.", "Đậu hũ non cắt khối vuông nhỏ 2cm.", "Thịt băm xào săn với chút dầu ăn và gừng băm khử mùi tanh.", "Đổ 1 lít nước vào đun sôi, thả đậu hũ non và rong biển vào nấu sôi lăn tăn trong 5 phút.", "Nêm hạt nêm nước tương ngon vừa ăn, rắc hành hoa và vài giọt dầu mè thơm ngát."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('c9dfe2c5-42b8-55f2-8de8-3d7f7daba1ce', 'Sườn xào chua ngọt', 'man', 4, '["Sườn non rửa sạch, chặt miếng 3cm, chần sơ nước sôi rồi ướp chút hạt nêm.", "Chiên sườn vàng đều hai mặt rồi vớt ra đĩa.", "Cà chua bổ múi cau, ớt chuông và hành tây cắt miếng vuông.", "Pha sốt chua ngọt: nước mắm, đường, giấm táo, tương cà.", "Phi thơm tỏi, trút cà chua, hành tây vào xào, sau đó cho sườn và sốt chua ngọt đảo đều 5 phút."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('cafef743-eb49-5ac5-aa45-758039839866', 'Salad Nga thập cẩm khoai tây jambon', 'rau', 4, '["Khoai tây, cà rốt gọt vỏ cắt hạt lựu, luộc chín mềm vừa tới rồi vớt ra ngâm nước lạnh cho ráo.", "Đậu Hà Lan và bắp ngọt chần sơ nước sôi.", "Thịt nguội jambon thái hạt lựu, dưa chuột muối thái hạt lựu.", "Trứng gà luộc chín bóc vỏ cắt hạt lựu.", "Cho toàn bộ các nguyên liệu vào âu lớn, thêm sốt Mayonnaise, chút muối tiêu trộn nhẹ tay cho sốt bao đều rồi để ngăn mát 30 phút."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('cdb399c4-c144-5158-a479-8f275da2aa33', 'Bắp bò luộc gừng sả', 'man', 4, '["Bắp bò hoa rửa sạch, dùng chỉ bọc tròn để khi thái lát có vân đẹp.", "Sả cây đập dập cắt khúc lót dưới đáy nồi, thêm vài lát gừng và củ hành tím.", "Cho bắp bò vào nồi cùng 2 muỗng nước mắm ngon, 1 muỗng đường, tiêu hạt.", "Đổ nước ngập ngang mặt thịt, đun sôi rồi hạ nhỏ lửa luộc trong 40 phút đến khi thịt chín mềm.", "Vớt bắp bò ra ngâm nước đá, để thật nguội rồi thái lát mỏng chấm mắm gừng hoặc tương gừng."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('ce055807-2682-5ede-89b9-2dba5ae77ee1', 'Cá nục kho cà chua', 'man', 4, '["Cá nục làm sạch ruột mang, cắt đôi nếu cá to, rửa sạch với nước muối loãng.", "Ướp cá với chút muối tiêu, chiên sơ hai mặt cho cá săn chắc không bị nát khi kho.", "Cà chua bổ múi cau, hành tím thái lát mỏng.", "Xếp một lớp cà chua dưới đáy nồi, đặt cá nục lên, phủ tiếp lớp cà chua bên trên.", "Nêm nước mắm, đường, hạt nêm, đổ nước dừa hoặc nước sôi ngập cá, đun sôi rồi hạ nhỏ lửa kho 45 phút cho nhừ xương."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('d2bdcb00-d106-54b6-a3de-8572c4884288', 'Cơm chiên kim chi phô mai Hàn Quốc', 'man', 4, '["Kim chi cải thảo thái nhỏ, thịt ba chỉ hoặc xúc xích thái hạt lựu.", "Xào săn thịt ba chỉ trên chảo lửa lớn cho xém cạnh, trút kim chi và 1 muỗng tương ớt Hàn Quốc (Gochujang) vào xào thơm.", "Cho cơm nguội vào chảo dằm tơi hạt cơm, đảo đều tay trên lửa lớn cho hạt cơm săn bóng ngấm vị chua cay.", "Tạo khoảng trống ở giữa chảo, cho phô mai Mozzarella bào sợi vào đậy vung hạ nhỏ lửa 2 phút cho phô mai tan chảy kéo sợi.", "Rắc rong biển vụn và mè rang thơm lừng lên trên chảo cơm chiên nóng hổi."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('d2f6f28a-b49d-550f-b941-20965f78a37c', 'Canh cá thác lác nấu khổ qua', 'canh', 4, '["Cá thác lác nạo quết thật dai dẻo với hành tím băm, tiêu xay, chút muối và thì là.", "Khổ qua rửa sạch bỏ ruột bào lát mỏng xéo.", "Đun sôi 1 lít nước lọc hoặc nước hầm xương với vài hạt muối.", "Dùng thìa múc từng viên chả cá thả vào nồi nước sôi đun 5 phút cho chả cá chín nổi lên mặt.", "Thả khổ qua vào nấu sôi lại trong 1 phút để khổ qua chín tới giòn ngọt không đắng, nêm nước mắm rắc hành thì là."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('d302c6a5-c1b5-5527-9384-17113f8967fb', 'Mì Udon xào thịt bò và rau cải', 'man', 4, '["Mì Udon chần qua nước sôi 1 phút cho sợi mì tơi mềm, xả nước lạnh để ráo.", "Thịt bò thái lát mỏng ướp nước tương, dầu hào và tiêu.", "Bắp cải, cà rốt thái sợi, hành tây bổ múi cau.", "Xào thịt bò trên lửa lớn vừa chín tái thì gắp riêng ra đĩa.", "Xào rau củ chín giòn, cho mì Udon và thịt bò vào cùng sốt xào Nhật Bản đảo đều tay trên lửa lớn 2 phút rồi rắc mè rang."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('d4ba170e-cd15-5e5a-a8a7-86a3425d0b6c', 'Cơm gà Teriyaki kiểu Nhật', 'man', 4, '["Thịt má đùi gà rút xương khía nhẹ mặt thịt, ướp chút muối tiêu.", "Pha sốt Teriyaki: 3 muỗng nước tương Nhật, 2 muỗng rượu Mirin (hoặc giấm táo), 2 muỗng đường, 1 muỗng gừng băm.", "Áp chảo thịt gà với mặt da xuống trước trên lửa vừa đến khi da vàng giòn, lật mặt thịt áp chảo thêm 3 phút.", "Đổ sốt Teriyaki vào chảo đun sôi liu riu, lật đều hai mặt miếng gà đến khi sốt keo sánh bám óng ánh quanh miếng thịt.", "Cắt gà thành từng dải dày xếp lên tô cơm nóng, rưới sốt Teriyaki và rắc mè trắng rang."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('d4cf10ec-56b5-51b8-9089-7cbf8f262325', 'Canh hoa thiên lý thịt bò', 'canh', 4, '["Hoa thiên lý nhặt cuống sâu úa, ngâm nước muối loãng 5 phút rồi rửa sạch để ráo.", "Thịt bò thăn thái lát mỏng ướp tỏi băm, hạt nêm, tiêu và chút dầu ăn.", "Phi thơm tỏi trong nồi, xào thịt bò trên lửa lớn vừa chín tái thì trút riêng ra đĩa.", "Đổ 1 lít nước vào nồi đun sôi bùng, nêm nước mắm hạt nêm vừa ăn.", "Thả hoa thiên lý vào nấu sôi 1 phút cho vừa chín tới giữ độ giòn ngọt, trút thịt bò vào đảo đều rồi tắt bếp ngay."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('d5df9201-c170-5f73-b9d0-6dde31008e23', 'Đậu hũ chiên sả ớt', 'man', 4, '["Đậu hũ trắng rửa nhẹ, dùng khăn thấm khô, cắt miếng vuông vừa ăn.", "Chiên đậu hũ trong chảo dầu ngập lửa vừa đến khi bốn mặt vàng ươm giòn rụm rồi vớt ra.", "Sả băm nhỏ, ớt hiểm băm nhuyễn, tỏi băm thơm.", "Chắt bớt dầu trong chảo, cho sả tỏi ớt vào phi thật vàng thơm giòn.", "Nêm chút muối, đường, hạt nêm vào sả rồi trút đậu hũ chiên vào xóc đều tay 1 phút cho bám quanh miếng đậu."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('d773ca07-9490-5ee9-8d1a-ce931bf13ea9', 'Mì xào hải sản kiểu Singapore', 'man', 4, '["Mì trứng chần nước sôi xả nước lạnh cho sợi mì tơi giòn.", "Tôm bóc vỏ, mực khía hoa cắt miếng vừa ăn xào chín tới rồi múc ra đĩa.", "Cải ngọt, cà rốt thái sợi, giá đỗ rửa sạch.", "Phi thơm tỏi ớt xào rau củ chín giòn, cho mì trứng và hải sản vào đảo nhanh tay trên lửa lớn.", "Rưới sốt xào hải sản dầu hào nước tương tiêu vào đảo đều trong 2 phút rồi rắc hành ngò tiêu xay."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('e1556065-8131-5dc0-8b9a-b0c97a2d06a8', 'Rau lang xào tỏi', 'rau', 4, '["Rau khoai lang nhặt đọt non, tước bớt phần xơ cuống lá, rửa sạch nhiều lần.", "Chần nhanh rau lang qua nước sôi 30 giây để giữ màu xanh mướt.", "Tỏi bóc vỏ đập dập thơm.", "Làm nóng chảo với nhiều dầu ăn, phi thơm tỏi trên lửa lớn.", "Cho rau lang vào đảo nhanh tay, nêm chút hạt nêm và nước mắm ngon, xào 2 phút rau vừa chín tới rồi trút ra đĩa."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('e7d281e3-8c24-5e4f-bdb6-2f748d802eaf', 'Thịt ba chỉ rang cháy cạnh', 'man', 4, '["Thịt ba chỉ rửa sạch, thái lát mỏng vừa ăn.", "Hành lá rửa sạch cắt khúc, hành tím thái lát.", "Cho thịt vào chảo đảo đều tay trên lửa vừa đến khi thịt tiết bớt mỡ và xém cạnh vàng nâu.", "Chắt bớt mỡ thừa ra, cho hành tím vào phi thơm cùng thịt.", "Nêm nước mắm, đường, tiêu đảo nhanh tay đến khi sốt bám bóng miếng thịt, rắc hành lá rồi tắt bếp."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('e8e1fa2e-baea-5c90-917d-01dd0343c3c0', 'Rau muống xào tỏi', 'rau', 4, '["Rau muống nhặt khúc non, bỏ bớt lá già, rửa sạch để ráo.", "Đun sôi nồi nước có chút muối, chần nhanh rau muống 30 giây rồi vớt ra xả nước lạnh giữ màu xanh giòn.", "Tỏi bóc vỏ đập dập, chia làm hai phần.", "Làm nóng chảo với dầu ăn trên lửa lớn, phi thơm một nửa tỏi.", "Trút rau muống vào đảo nhanh tay, nêm nước mắm hạt nêm, cho nốt phần tỏi còn lại vào đảo đều 1 phút rồi tắt bếp."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('e92e9053-48c3-5a24-82fa-4e210cd36a81', 'Ếch xào sả ớt', 'man', 4, '["Thịt ếch làm sạch, lột da hoặc giữ da tùy thích, chặt miếng vừa ăn.", "Ướp ếch với hành tỏi băm, 1/2 lượng sả ớt, bột nghệ, nước mắm, tiêu trong 20 phút.", "Chiên sơ thịt ếch trên chảo dầu nóng cho thịt săn vàng giòn.", "Phi thơm lượng sả ớt còn lại với hành tỏi trên chảo, trút ếch vào đảo đều trên lửa lớn.", "Nêm nếm lại gia vị, thêm chút ớt chuông hoặc hành tây đảo đều 2 phút rồi tắt bếp."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('ea7d1369-7f04-55f7-8fff-3016b75e605a', 'Bông cải trắng xào tỏi', 'rau', 4, '["Bông cải trắng cắt thành các nhánh nhỏ vừa ăn, ngâm nước muối loãng 5 phút rồi rửa sạch.", "Chần nhanh qua nước sôi 1 phút rồi vớt ra để ráo.", "Làm nóng chảo với dầu ăn, phi thơm tỏi đập dập.", "Cho bông cải vào xào nhanh tay trên lửa lớn, nêm dầu hào, hạt nêm.", "Rắc hành lá thái nhỏ và tiêu xay thơm rồi trút ra đĩa dùng nóng."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('ec858fb7-ab17-503f-8abe-519f7aa63a65', 'Cải ngọt xào tỏi', 'rau', 4, '["Cải ngọt cắt gốc, rửa sạch từng bẹ lá, cắt khúc dài 4-5cm.", "Tỏi bóc vỏ đập dập thơm.", "Làm nóng chảo với dầu ăn, phi thơm tỏi vàng óng trên lửa lớn.", "Trút phần cọng cải vào xào trước 1 phút, sau đó cho phần lá vào xào chung.", "Nêm hạt nêm dầu hào vừa ăn, đảo nhanh tay thêm 1 phút cho rau chín giòn rồi trút ra đĩa."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('ef99e7d7-b92c-59c6-a9ab-6ab1402e2525', 'Thịt kho măng tươi', 'man', 4, '["Măng tươi luộc 2-3 lần với chút muối mở nắp để khử hết độc và đắng, xé miếng vừa ăn.", "Thịt ba chỉ thái con chì, ướp hành tỏi băm, nước mắm, hạt nêm, đường trong 20 phút.", "Xào săn thịt trên chảo, sau đó trút măng vào xào chung cho ngấm gia vị.", "Đổ thêm nước xâm xấp mặt thịt, kho lửa nhỏ khoảng 25 phút cho thịt mềm và măng giòn ngọt.", "Rắc hành lá, tiêu xay rồi múc ra đĩa dùng với cơm nóng."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('f157ea09-e359-504e-8421-8f706a3b58b9', 'Trứng chiên thịt băm', 'man', 4, '["Thịt heo nạc vai băm nhỏ hoặc xay nhuyễn.", "Đập 4 quả trứng gà vào tô, thêm thịt băm, hành tím băm nhỏ, hành lá cắt nhỏ, 1 muỗng nước mắm, tiêu.", "Đánh tan đều trứng và thịt để gia vị hòa quyện.", "Làm nóng chảo với 2 muỗng dầu ăn, đổ hỗn hợp trứng thịt vào đậy vung hạ lửa nhỏ để thịt chín đều.", "Khi mặt dưới vàng đều, lật mặt trên chiên tiếp 2 phút đến khi hai mặt vàng thơm nở xốp."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('f39a20c1-e85a-51c8-98eb-9f01de428ada', 'Canh bắp cải cuộn thịt', 'canh', 4, '["Bắp cải tách từng lá to nguyên vẹn, chần qua nước sôi 1 phút cho lá mềm dai dễ cuộn.", "Thịt nạc vai xay nhuyễn trộn cùng nấm mèo, cà rốt băm nhỏ, hành tím, nước mắm, tiêu.", "Trải lá bắp cải ra, cho nhân thịt vào giữa rồi cuộn tròn lại như cuốn nem, buộc bằng cọng hành lá chần mềm.", "Đun sôi 1 lít nước dùng trên nồi, thả từng cuộn bắp cải vào nấu lửa vừa trong 15 phút.", "Nước canh ngọt thanh từ bắp cải và thịt băm, nêm hạt nêm nước mắm vừa miệng, rắc tiêu hành hoa."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('f65f9b16-0644-5891-acf0-38aa9193058a', 'Canh mướp đắng nhồi thịt', 'canh', 4, '["Mướp đắng cắt khúc 4cm, dùng thìa móc sạch ruột hạt trắng bên trong, chần sơ nước sôi cho bớt đắng.", "Thịt nạc vai băm trộn đều với nấm mèo băm nhỏ, hành tím, chút miến cắt nhỏ, nước mắm và tiêu.", "Nhồi phần thịt băm vào giữa từng khúc mướp đắng, miết phẳng hai đầu.", "Đun sôi 1.2 lít nước hầm xương hoặc nước lọc có nêm chút muối hạt.", "Thả từng khúc mướp đắng nhồi thịt vào nấu nhỏ lửa mở nắp trong 20 phút cho mướp đắng chín mềm trong và nước canh ngọt thanh.", "Nêm nước mắm hạt nêm vừa ăn, rắc hành lá mùi tàu thái nhỏ."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('fa169063-ab1e-59e5-a1cf-d664f420473f', 'Salad Caesar ức gà nướng', 'rau', 4, '["Ức gà ướp chút muối, tiêu, dầu oliu và tỏi băm, áp chảo chín vàng hai mặt rồi thái lát xéo.", "Rau xà lách Romaine rửa sạch ngắt khúc 4cm để ráo nước thật giòn.", "Bánh mì sandwich cắt hạt lựu nướng vàng giòn với chút bơ tỏi.", "Pha sốt Caesar: sốt mayonnaise, phô mai Parmesan bào, tỏi băm, nước cốt chanh vàng, tiêu đen.", "Trộn đều xà lách với sốt Caesar, xếp ức gà nướng và bánh mì giòn lên trên, rắc thêm phô mai Parmesan bào nhuyễn."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('fb9f23b8-54a9-5ff9-8a20-7039100dca63', 'Canh cua rau đay mồng tơi mướp', 'canh', 4, '["Cua đồng giã nhuyễn lọc lấy nước thịt cua, khêu gạch cua trong mai để riêng.", "Rau đay, mồng tơi nhặt lá non rửa sạch thái nhỏ, mướp gọt vỏ bổ đôi thái vát chéo.", "Cho nước cua vào nồi cùng 1 thìa muối nhỏ, khuấy đều rồi bắc lên bếp đun lửa vừa không đậy vung.", "Khi thịt cua nổi thành từng mảng gạch dày kết tủa trên mặt, nhẹ nhàng gạt thịt cua sang bên hoặc vớt riêng ra bát.", "Thả mướp và rau đay mồng tơi vào nồi nước sôi đun 3 phút cho rau chín xanh, nêm nước mắm vừa ăn.", "Trút thịt cua và gạch cua chưng thơm vào nồi canh, ăn cùng cà pháo giòn tan."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('fdbfb928-c573-5d67-8799-45c1c4d6a02c', 'Súp gà kem bắp non kiểu Âu', 'canh', 4, '["Ức gà luộc chín xé sợi mỏng, giữ lại nước luộc gà ngọt thanh.", "Bắp ngọt tách hạt luộc chín, nấm hương ngâm nở thái sợi mỏng.", "Đun sôi nước luộc gà, cho bắp non, nấm hương và gà xé vào nấu trên lửa vừa 10 phút.", "Hòa tan bột bắp với nước lọc, từ từ đổ vào nồi súp khuấy đều tay đến khi súp sánh mịn.", "Đánh tan lòng trắng trứng, rưới từ từ qua rây vào nồi súp khuấy nhẹ tạo vân sợi trắng đẹp mắt, thêm chút kem sữa tươi rắc tiêu ngò."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('feb47d19-0c17-5fd8-aba7-be63e02c31ec', 'Canh rau ngót nấu thịt băm', 'canh', 4, '["Rau ngót tuốt lá, rửa sạch ngâm nước muối loãng, dùng tay vò hơi dập lá để rau mềm ngọt nước khi nấu.", "Thịt nạc vai băm nhỏ ướp chút hạt nêm và hành tím băm.", "Phi thơm hành tím với 1 muỗng dầu ăn, cho thịt băm vào xào săn chín.", "Cho rau ngót vào xào cùng thịt khoảng 1-2 phút cho ngấm gia vị.", "Đổ 1 lít nước lọc vào đun sôi bùng lên trong 3-4 phút cho rau ngót chín mềm nước ngọt lịm, nêm nước mắm vừa ăn rồi tắt bếp."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('fed27ada-1ccf-5aa7-979f-7690bbb03002', 'Canh cà chua trứng đậu phụ', 'canh', 4, '["Cà chua bổ múi cau, đậu hũ non cắt khối vuông nhỏ.", "Đập 2 quả trứng gà ra bát đánh tan đều.", "Phi thơm hành tím xào cà chua cho mềm nhừ đỏ au.", "Đổ 900ml nước lọc vào đun sôi, thả đậu hũ non vào nấu sôi lăn tăn 3 phút.", "Hạ nhỏ lửa, từ từ rưới trứng vào nồi đồng thời khuấy nhẹ theo một chiều tạo vân mây trứng bồng bềnh, rắc hành lá mùi tàu."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipes (id, name, category, servings, instructions) VALUES ('ff80b493-e40b-51bb-8251-3b18023b33de', 'Canh tôm nấu rau dền đỏ', 'canh', 4, '["Rau dền đỏ nhặt lá non, rửa sạch để ráo nước.", "Tôm sú bóc vỏ băm nhỏ ướp chút muối tiêu hành tím.", "Xào săn tôm trên nồi với 1 muỗng dầu ăn.", "Đổ 1 lít nước vào đun sôi bùng, thả rau dền vào nấu lửa vừa khoảng 3 phút đến khi rau mềm chín nước có màu tím đỏ tuyệt đẹp.", "Nêm nước mắm hạt nêm ngọt lành thanh nhiệt ngày hè."]'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('000888e7-88de-5217-a3c2-78659d24b88c', '11111111-0001-0000-0000-000000000002', 100, 'g') ON CONFLICT (recipe_id, ingredient_id) DO NOTHING;
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('000888e7-88de-5217-a3c2-78659d24b88c', '11111111-0001-0000-0000-000000000007', 150, 'g') ON CONFLICT (recipe_id, ingredient_id) DO NOTHING;
INSERT INTO public.recipe_ingredients (recipe_id, ingredient_id, quantity, unit) VALUES ('000888e7-88de-5217-a3c2-78659d24b88c', '11111111-0001-0000-0000-000000000026', 20, 'g') ON CONFLICT (recipe_id, ingredient_id) DO NOTHING;
